24	struct ExportStatus {
25	    enum class Code { Ok, IoError, EmptyReport };
26	    Code               code{Code::Ok};
27	    std::string        message;
28	    [[nodiscard]] bool ok() const noexcept { return code == Code::Ok; }
29	};
