31	/**
32	 * @brief MessreiheReportExporter - persistiert MessreiheReport in CSV + TikZ
33	 * @subsystem MessungDriver
34	 *
35	 * Beispiel:
36	 *   auto report = orchestrator.run_default_lookup_messreihe(workload);
37	 *   MessreiheReportExporter ex;
38	 *   ex.write_csv(report, "results.csv");
39	 *   ex.write_tikz_summary(report, "summary.tex");
40	 */
41	class MessreiheReportExporter {
42	public:
43	    /// CSV-Export: 12 Spalten pro PermutationOutcome
44	    [[nodiscard]] ExportStatus write_csv(const MessreiheReport& report, const std::filesystem::path& out_path) const {
45	        if (report.outcomes.empty()) { return {ExportStatus::Code::EmptyReport, "report has no outcomes"}; }
46	        std::ofstream f(out_path);
47	        if (!f.is_open()) { return {ExportStatus::Code::IoError, "cannot open output: " + out_path.string()}; }
48	        f << "axis_id,variant_name,verdict,welch_p_value,throughput_ratio,"
49	          << "ee_a_engine,ee_a_throughput,ee_a_p99_ns,ee_a_cache_misses,"
50	          << "ee_b_engine,ee_b_throughput,ee_b_p99_ns\n";
51	        for (const auto& outcome : report.outcomes) {
52	            f << outcome.axis_id << ',' << outcome.variant_name << ',' << verdict_string(outcome.verdict) << ','
53	              << outcome.welch_p_value << ',' << outcome.throughput_ratio << ',' << outcome.ee_a_result.engine_name
54	              << ',' << outcome.ee_a_result.throughput_ops_per_sec << ',' << outcome.ee_a_result.latency_p99.count()
55	              << ',' << outcome.ee_a_result.total_cache_misses << ',' << outcome.ee_b_result.engine_name << ','
56	              << outcome.ee_b_result.throughput_ops_per_sec << ',' << outcome.ee_b_result.latency_p99.count() << '\n';
57	        }
58	        return {};
59	    }
60	
61	    /// TikZ-Summary: Stacked-Bar Wins/Ties/Losses pro Achse
62	    [[nodiscard]] ExportStatus write_tikz_summary(const MessreiheReport&       report,
63	                                                  const std::filesystem::path& out_path) const {
64	        if (report.outcomes.empty()) { return {ExportStatus::Code::EmptyReport, "report has no outcomes"}; }
65	        std::ofstream f(out_path);
66	        if (!f.is_open()) { return {ExportStatus::Code::IoError, "cannot open output: " + out_path.string()}; }
67	
68	        std::map<std::string, std::array<std::size_t, 3>> per_axis; // [ee_a_wins, ee_b_wins, ties]
69	        for (const auto& o : report.outcomes) {
70	            auto& bucket = per_axis[o.axis_id];
71	            switch (o.verdict) {
72	                case cmd::CompareEngineCommand::Verdict::EE_A_Wins: ++bucket[0]; break;
73	                case cmd::CompareEngineCommand::Verdict::EE_B_Wins: ++bucket[1]; break;
74	                case cmd::CompareEngineCommand::Verdict::Tie: ++bucket[2]; break;
75	                default: break;
76	            }
77	        }
78	
79	        f << "% V34.B.1 TikZ-Summary fuer MessreiheReport\n"
80	          << "% Pro Achse: stacked-bar (EE-A wins, EE-B wins, Ties)\n"
81	          << "\\begin{tikzpicture}\n"
82	          << "\\begin{axis}[\n"
83	          << "    ybar stacked, bar width=12pt,\n"
84	          << "    legend style={at={(0.5,-0.18)}, anchor=north, legend columns=3},\n"
85	          << "    ylabel={Anzahl Permutationen},\n"
86	          << "    xlabel={Achse},\n"
87	          << "    symbolic x coords={";
88	        bool first = true;
89	        for (const auto& [axis_id, _] : per_axis) {
90	            if (!first) f << ',';
91	            f << axis_id;
92	            first = false;
93	        }
94	        f << "},\n"
95	          << "    xtick=data,\n"
96	          << "    ymin=0]\n"
97	          << "\\addplot+[fill=green!60] coordinates {";
98	        for (const auto& [axis_id, b] : per_axis) { f << "(" << axis_id << ',' << b[0] << ") "; }
99	        f << "};\n"
100	          << "\\addplot+[fill=orange!60] coordinates {";
101	        for (const auto& [axis_id, b] : per_axis) { f << "(" << axis_id << ',' << b[1] << ") "; }
102	        f << "};\n"
103	          << "\\addplot+[fill=gray!40] coordinates {";
104	        for (const auto& [axis_id, b] : per_axis) { f << "(" << axis_id << ',' << b[2] << ") "; }
105	        f << "};\n"
106	          << "\\legend{EE-A wins (CacheEngine), EE-B wins (PrtArt), Tie}\n"
107	          << "\\end{axis}\n"
108	          << "\\end{tikzpicture}\n";
109	        f << "% Total: axes=" << report.total_axes << " variants=" << report.total_variants
110	          << " ee_a_wins=" << report.ee_a_wins << " ee_b_wins=" << report.ee_b_wins << " ties=" << report.ties
111	          << " elapsed_ns=" << report.total_elapsed.count() << "\n";
112	        return {};
113	    }
114	
115	private:
116	    static std::string_view verdict_string(cmd::CompareEngineCommand::Verdict v) {
117	        switch (v) {
118	            case cmd::CompareEngineCommand::Verdict::EE_A_Wins: return "EE_A_Wins";
119	            case cmd::CompareEngineCommand::Verdict::EE_B_Wins: return "EE_B_Wins";
120	            case cmd::CompareEngineCommand::Verdict::Tie: return "Tie";
121	            case cmd::CompareEngineCommand::Verdict::InconclusiveData: return "Inconclusive";
122	        }
123	        return "Unknown";
124	    }
125	};
